import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]; BASE=ROOT/"problems"/"arrays"
tasks=[
 ("81-maximum-product-of-two-elements","Maximum Product of Two Elements","Easy","Traversal","maxProductOfTwoElements","int",["2 <= nums.length <= 100000","1 <= nums[i] <= 10000"],"O(n)","O(1)","Choose two different elements of a positive integer array `nums`. Return the largest possible product of their values. Input: `nums`. Output: the maximum pair product.","        first = second = 0\n        for x in nums:\n            if x > first: first, second = x, first\n            elif x > second: second = x\n        return first * second","        int first = 0, second = 0;\n        for (int x : nums) { if (x > first) { second = first; first = x; } else if (x > second) second = x; }\n        return first * second;",[([3,4,5,2],20),([1,5,4,5],20)],[[1,2],[2,2],[1,1,1],[9,8,7],[10,1,10],[5,4,3,2],[10000,9999],[6,7,7,1],[3,100,2,99],[8,8,8,8]]),
 ("82-sum-of-unique-elements","Sum of Unique Elements","Easy","Traversal","sumOfUnique","int",["1 <= nums.length <= 1000","1 <= nums[i] <= 1000"],"O(n)","O(n)","Given an integer array `nums`, return the sum of values that occur exactly once. If no value occurs exactly once, return 0. Input: `nums`. Output: the unique-value sum.","        counts = Counter(nums)\n        return sum(x for x, count in counts.items() if count == 1)","        Map<Integer, Integer> counts = new HashMap<>();\n        for (int x : nums) counts.put(x, counts.getOrDefault(x, 0) + 1);\n        int sum = 0; for (Map.Entry<Integer, Integer> e : counts.entrySet()) if (e.getValue() == 1) sum += e.getKey();\n        return sum;",[([1,2,3,2],4),([1,1,1],0)],[[1],[1,2],[2,2],[1,2,3,4],[1,1,2,2,3],[9,8,7,6],[5,5,6,7,7],[10,20,10,30],[1000,999,999],[4,3,2,1,4,3]]),
 ("83-divide-array-into-equal-pairs","Divide Array Into Equal Pairs","Easy","Traversal","canDivideIntoPairs","boolean",["2 <= nums.length <= 100000","nums.length is even","1 <= nums[i] <= 500"],"O(n)","O(1)","An array can be divided into pairs when every element belongs to exactly one pair of equal values. Given an even-length array `nums`, return whether such a division is possible. Input: `nums`. Output: true if every value has even frequency.","        counts = [0] * 501\n        for x in nums: counts[x] ^= 1\n        return not any(counts)","        int[] parity = new int[501];\n        for (int x : nums) parity[x] ^= 1;\n        for (int x : parity) if (x != 0) return false;\n        return true;",[([3,2,3,2,2,2],True),([1,2,3,4],False)],[ [1,1],[2,2,2,2],[1,1,2,2],[1,2,1,2],[1,1,1,1,2,2],[5,5,6,6,7,7],[1,2,3,1,2,3],[9,9,9,9],[500,500],[2,2,3,3,4,4] ]),
 ("84-minimum-average-difference-index","Minimum Average Difference Index","Medium","Prefix/Suffix","minimumAverageDifference","int",["1 <= nums.length <= 100000","0 <= nums[i] <= 100000"],"O(n)","O(1)","For each index `i`, compute the absolute difference between the integer average of elements `0..i` and the integer average of elements `i+1..n-1`. Use floor division; the right average is 0 when the right side is empty. Return the smallest index with the minimum difference. Input: `nums`. Output: the selected index.","        total = sum(nums)\n        left = 0\n        best, answer = None, 0\n        n = len(nums)\n        for i, x in enumerate(nums):\n            left += x\n            left_avg = left // (i + 1)\n            right_avg = (total - left) // (n - i - 1) if i + 1 < n else 0\n            diff = abs(left_avg - right_avg)\n            if best is None or diff < best: best, answer = diff, i\n        return answer","        long total = 0, left = 0; for (int x : nums) total += x;\n        long best = Long.MAX_VALUE; int answer = 0;\n        for (int i = 0; i < nums.length; i++) { left += nums[i]; long a = left / (i + 1); long b = i + 1 < nums.length ? (total-left)/(nums.length-i-1) : 0; long d = Math.abs(a-b); if (d < best) { best=d; answer=i; } }\n        return answer;",[([2,5,3,9,5,3],3),([0],0)],[[1],[1,2],[2,2],[1,2,3,4],[10,0,0,0],[0,0,0],[5,5,5,5],[1,100,1],[100,1,1,1],[3,1,2,4,5]]),
 ("85-minimum-score-range-of-k-students","Minimum Score Range of K Students","Easy","Traversal","minimumScoreRange","int",["1 <= k <= nums.length <= 100000","0 <= nums[i] <= 100000"],"O(n log n)","O(n)","Given test scores `nums` and an integer `k`, choose any `k` scores. Return the smallest possible difference between the largest and smallest chosen score. Input: `nums`, `k`. Output: the minimum range.","        a = sorted(nums)\n        return min(a[i + k - 1] - a[i] for i in range(len(a) - k + 1))","        int[] a = nums.clone(); Arrays.sort(a); int best = Integer.MAX_VALUE;\n        for (int i = 0; i + k <= a.length; i++) best = Math.min(best, a[i+k-1]-a[i]);\n        return best;",[({"nums":[90,7,5,9,2,1],"k":3},2),({"nums":[4,4,4],"k":2},0)],[{"nums":[1],"k":1},{"nums":[1,2],"k":2},{"nums":[1,2,3,4],"k":1},{"nums":[1,10,20,30],"k":2},{"nums":[10,20,30],"k":2},{"nums":[7,7,8,9],"k":3},{"nums":[100,1,50,51],"k":2},{"nums":[0,100000,99999],"k":2},{"nums":[5,1,9,3,7],"k":3}]),
 ("86-minimize-maximum-pair-sum","Minimize the Maximum Pair Sum","Medium","Traversal","minPairSum","int",["2 <= nums.length <= 100000","nums.length is even","1 <= nums[i] <= 100000"],"O(n log n)","O(n)","Pair every element of an even-length array with exactly one other element. The pair sum is the sum of its two values. Return the smallest possible value of the largest pair sum. Input: `nums`. Output: the minimized largest pair sum.","        a = sorted(nums)\n        return max(a[i] + a[-1-i] for i in range(len(a) // 2))","        int[] a = nums.clone(); Arrays.sort(a); int best = 0;\n        for (int i = 0; i < a.length / 2; i++) best = Math.max(best, a[i] + a[a.length-1-i]);\n        return best;",[([3,5,2,3],7),([3,5,4,2,4,6],8)],[[1,1],[1,2],[2,2,2,2],[1,2,3,4],[1,10,2,9],[5,4,3,2,1,6],[100000,1,99999,2],[7,7,7,7],[9,1,8,2,7,3],[4,4,5,5]]),
 ("87-maximum-sum-after-k-negations","Maximum Sum After K Negations","Medium","Traversal","largestSumAfterKNegations","long",["1 <= nums.length <= 100000","-100000 <= nums[i] <= 100000","0 <= k <= 100000"],"O(n log n)","O(n)","You may choose an array element and negate it in one operation. Apply exactly `k` operations to maximize the final sum; the same element may be chosen multiple times. Input: `nums`, `k`. Output: the maximum sum.","        a = sorted(nums)\n        for i in range(len(a)):\n            if k and a[i] < 0: a[i] = -a[i]; k -= 1\n        total = sum(a)\n        if k % 2: total -= 2 * min(a)\n        return total","        int[] a = nums.clone(); Arrays.sort(a);\n        for (int i = 0; i < a.length && k > 0 && a[i] < 0; i++, k--) a[i] = -a[i];\n        long sum = 0; int min = Integer.MAX_VALUE; for (int x : a) { sum += x; min = Math.min(min, x); }\n        return (k & 1) == 1 ? sum - 2L * min : sum;",[({"nums":[4,2,3],"k":1},5),({"nums":[3,-1,0,2],"k":3},6)],[{"nums":[1],"k":0},{"nums":[-1],"k":1},{"nums":[-4,-2,-3],"k":4},{"nums":[-2,0,2],"k":0},{"nums":[-1,-2,3,4],"k":2},{"nums":[5,6,9,10],"k":1},{"nums":[-8,3,-5,1],"k":3},{"nums":[0,0,0],"k":5},{"nums":[100000,-100000],"k":1}]),
 ("88-recover-original-from-doubled-array","Recover Original Array From Doubled Array","Medium","Traversal","findOriginalArray","int[]",["0 <= changed.length <= 100000","changed.length is even","0 <= changed[i] <= 100000"],"O(n log n)","O(n)","An array `changed` was formed by taking an original array and adding twice each original value, then shuffling the result. Recover and return the original values in non-decreasing order. If no original array is possible, return an empty array. Input: `changed`. Output: the recovered sorted array or empty array.","        if len(changed) % 2: return []\n        counts = Counter(changed)\n        answer = []\n        for x in sorted(changed):\n            if counts[x] == 0: continue\n            if x == 0:\n                if counts[x] < 2: return []\n                counts[x] -= 2; answer.append(0); continue\n            if counts[2*x] == 0: return []\n            counts[x] -= 1; counts[2*x] -= 1; answer.append(x)\n        return answer if len(answer) * 2 == len(changed) else []","        if ((changed.length & 1) == 1) return new int[0];\n        int[] a = changed.clone(); Arrays.sort(a); Map<Integer, Integer> count = new HashMap<>(); for (int x : a) count.put(x, count.getOrDefault(x,0)+1);\n        int[] out = new int[changed.length/2]; int at = 0;\n        for (int x : a) { int c = count.getOrDefault(x,0); if (c == 0) continue; if (x == 0) { if (c < 2) return new int[0]; count.put(0,c-2); out[at++]=0; } else { int d = count.getOrDefault(2*x,0); if (d == 0) return new int[0]; count.put(x,c-1); count.put(2*x,d-1); out[at++]=x; } }\n        return at == out.length ? out : new int[0];",[([1,3,4,2,6,8],[1,3,4]),([6,3,0,1],[])],[[],[0,0],[0,0,0,0],[1,2],[1,2,3],[2,4,8,16],[4,2,8,4],[1,2,2,4],[1,10,3,7,20,6],[5,5,10,10]]),
 ("89-maximize-happiness-of-selected-children","Maximize Happiness of Selected Children","Medium","Traversal","maximumHappiness","long",["1 <= happiness.length <= 100000","0 <= happiness[i] <= 1000000000","1 <= k <= happiness.length"],"O(n log n)","O(n)","There are children with happiness values in `happiness`. Choose exactly `k` children one at a time. Before the `i`th choice, every unchosen child's happiness has decreased by `i - 1`, but not below zero. Return the largest total happiness achievable. Input: `happiness`, `k`. Output: the maximum total.","        total = 0\n        for i, x in enumerate(sorted(happiness, reverse=True)[:k]): total += max(0, x - i)\n        return total","        int[] a = happiness.clone(); Arrays.sort(a); long total = 0;\n        for (int i = 0; i < k; i++) total += Math.max(0L, (long)a[a.length-1-i] - i);\n        return total;",[({"happiness":[1,2,3],"k":2},4),({"happiness":[1,1,1,1],"k":2},1)],[{"happiness":[5],"k":1},{"happiness":[0,0,0],"k":1},{"happiness":[2,2,2],"k":3},{"happiness":[10,9,8],"k":1},{"happiness":[10,9,8],"k":3},{"happiness":[1,2,3,4,5],"k":2},{"happiness":[5,4,3,2,1],"k":4},{"happiness":[100,1,1,1],"k":3},{"happiness":[1000000000,1000000000],"k":2}]),
 ("90-count-equal-divisible-index-pairs","Count Equal and Divisible Index Pairs","Medium","Traversal","countEqualDivisiblePairs","int",["1 <= nums.length <= 1000","1 <= nums[i] <= 100000","1 <= k <= 100000"],"O(n^2)","O(1)","Count pairs of indices `i < j` for which `nums[i] == nums[j]` and the product `i * j` is divisible by positive integer `k`. Input: `nums` and `k`. Output: the number of qualifying pairs.","        answer = 0\n        for i in range(len(nums)):\n            for j in range(i + 1, len(nums)):\n                if nums[i] == nums[j] and i * j % k == 0: answer += 1\n        return answer","        int answer = 0;\n        for (int i = 0; i < nums.length; i++) for (int j = i + 1; j < nums.length; j++) if (nums[i] == nums[j] && (long)i*j % k == 0) answer++;\n        return answer;",[({"nums":[3,1,2,2,2,1,3],"k":2},4),({"nums":[1,2,3,4],"k":1},0)],[{"nums":[1,1],"k":1},{"nums":[1,1,1],"k":2},{"nums":[2,2,2,2],"k":2},{"nums":[1,2,1,2,1],"k":3},{"nums":[5,5,5,5,5],"k":4},{"nums":[1,2,3,1,2,3],"k":5},{"nums":[9],"k":1},{"nums":[1,1,1,1],"k":10},{"nums":[4,3,4,3,4],"k":6}])
]

for i, task in enumerate(tasks):
    row=list(task)
    if row[0]=="81-maximum-product-of-two-elements": row[12]=[([3,4,5,2],20),([1,5,4,5],25)]
    if row[0]=="85-minimum-score-range-of-k-students": row[12]=[({"nums":[9,4,1,7],"k":2},2),({"nums":[4,4,4],"k":2},0)]
    tasks[i]=tuple(row)
roster_path=ROOT/"problems"/"roster.json"; roster=json.loads(roster_path.read_text())
for slug,title,diff,subtopic,method,ret,constraints,time,space,desc,py,java,examples,tests in tasks:
    folder=BASE/slug; folder.mkdir()
    params=[{"name":"nums","type":"int[]"}]
    if slug in ("85-minimum-score-range-of-k-students","89-maximize-happiness-of-selected-children"): params=[{"name":"nums" if slug.startswith("85-") else "happiness","type":"int[]"},{"name":"k","type":"int"}]
    if slug=="87-maximum-sum-after-k-negations": params=[{"name":"nums","type":"int[]"},{"name":"k","type":"int"}]
    if slug=="90-count-equal-divisible-index-pairs": params=[{"name":"nums","type":"int[]"},{"name":"k","type":"int"}]
    if slug=="88-recover-original-from-doubled-array": params=[{"name":"changed","type":"int[]"}]
    cases=[x for x,_ in examples]+tests
    def fmt(x): return ", ".join(f"{key} = {json.dumps(v)}" for key,v in x.items()) if isinstance(x,dict) else f"{params[0]['name']} = {json.dumps(x)}"
    def outfmt(y): return json.dumps(y,separators=(",",":")) if isinstance(y,list) else str(y)
    meta={"title":title,"difficulty":diff,"subtopic":subtopic,"companies":["Amazon","Google","Microsoft"],"description":desc,"constraints":constraints,"hints":["Sort or count values once, then process each candidate in a single pass.","Check duplicates, all-equal inputs, and boundary values for `k`."],"examples":[{"input":fmt(x),"output":outfmt(y)} for x,y in examples],"timeComplexity":time,"spaceComplexity":space,"compare":"exact","signature":{"kind":"function","method":method,"params":params,"returns":ret}}
    (folder/"problem.json").write_text(json.dumps(meta,indent=2)+"\n")
    pyparams="".join(f", {p['name']}: {'List[int]' if p['type']=='int[]' else 'int'}" for p in params)
    (folder/"solution.py").write_text(f"class Solution:\n    def {method}(self{pyparams}) -> {'List[int]' if ret=='int[]' else 'int'}:\n"+py+"\n")
    jparams=", ".join(f"{p['type']} {p['name']}" for p in params)
    jret={"int":"int","long":"long","boolean":"boolean","int[]":"int[]"}[ret]
    (folder/"Solution.java").write_text(f"class Solution {{\n    public {jret} {method}({jparams}) {{\n"+java+"\n    }\n}\n")
    (folder/"tests.py").write_text("def visible():\n    return "+repr([{"in":x if isinstance(x,dict) else {params[0]["name"]:x}} for x in cases[:3]])+"\n\ndef hidden():\n    return "+repr([{"in":x if isinstance(x,dict) else {params[0]["name"]:x}} for x in cases[3:]])+"\n")
    roster.setdefault("arrays",[]).append([slug,title,diff,subtopic,None])
roster_path.write_text(json.dumps(roster,indent=2)+"\n")
print(f"Created {len(tasks)} array questions")
